Ниже код целиком: 5 файлов и 2 небольшие вставки в существующий код. Я его не компилировал, потому что файлов проекта у меня нет. Первую сборку нужно проверить в Xcode.

## Как это работает

1. **При старте сессии** приложение записывает сессию (время начала и конца, 30 минут) в общее хранилище App Group. Затем оно ставит блокировку, регистрирует у системы расписание «закончить в 10:30» и запускает Live Activity.
2. **В момент окончания iOS сама запускает расширение DeviceActivityMonitor.** Это происходит, даже если приложение в фоне или выгружено. Расширение снимает блокировку, добавляет 30 минут к сегодняшнему дню и ставит отметку «Slumpy должен сказать „Сессия окончена“».
3. **Live Activity в это же время сама переключается на «Сессия окончена».** Ей заранее задано время, после которого она считается устаревшей, поэтому приложение для этого не нужно.
4. **При открытии приложения** оно убирает Live Activity и забирает отметку, после чего Slumpy говорит «Сессия окончена». Если расширение по какой-то причине не сработало, приложение само увидит, что время вышло, и сделает всё из пункта 2. Минуты при этом не засчитаются дважды.
5. Если приложение открыто в момент окончания, Slumpy скажет фразу сразу.

## Код

### 1. `ReadingSessionShared.swift`
Подключить к двум целям: **приложение** и **расширение DeviceActivityMonitor**.

```swift
import DeviceActivity
import Foundation
import ManagedSettings
import os

enum AppGroup {
    // Replace with your real App Group identifier.
    static let id = "group.com.example.slumpy"
}

private let logger = Logger(subsystem: "Slumpy", category: "ReadingSession")

struct ReadingSession: Codable, Sendable, Equatable {
    let id: UUID
    let startDate: Date
    let endDate: Date
    let plannedMinutes: Int
}

struct SharedState: Codable, Sendable {
    var activeSession: ReadingSession?
    var minutesByDay: [String: Int] = [:]
    var pendingAnnouncement = false

    func minutes(on date: Date) -> Int {
        minutesByDay[DayKey.make(for: date)] ?? 0
    }
}

enum DayKey {
    static func make(for date: Date) -> String {
        let c = Calendar.current.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", c.year ?? 0, c.month ?? 0, c.day ?? 0)
    }
}

/// JSON file in the App Group container, shared by the app and the monitor extension.
/// Every read-modify-write runs under an exclusive file lock because both processes may touch it at the same moment.
enum SharedStore {
    private static var containerURL: URL {
        guard let url = FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: AppGroup.id) else {
            fatalError("App Group \(AppGroup.id) is not enabled for this target")
        }
        return url
    }

    private static var stateURL: URL { containerURL.appending(path: "reading-session-state.json") }
    private static var lockURL: URL { containerURL.appending(path: "reading-session-state.lock") }

    static func read() -> SharedState {
        withLock { load() }
    }

    @discardableResult
    static func update<T>(_ change: (inout SharedState) -> T) -> T {
        withLock {
            var state = load()
            let result = change(&state)
            save(state)
            return result
        }
    }

    private static func load() -> SharedState {
        guard let data = try? Data(contentsOf: stateURL) else { return SharedState() }
        do {
            return try JSONDecoder().decode(SharedState.self, from: data)
        } catch {
            logger.error("Failed to decode shared state: \(error)")
            return SharedState()
        }
    }

    private static func save(_ state: SharedState) {
        do {
            let data = try JSONEncoder().encode(state)
            // The session can end while the phone is locked; this protection class keeps the file writable then.
            try data.write(to: stateURL, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
        } catch {
            logger.error("Failed to save shared state: \(error)")
        }
    }

    private static func withLock<T>(_ body: () -> T) -> T {
        let fd = open(lockURL.path(percentEncoded: false), O_CREAT | O_RDWR, 0o644)
        guard fd >= 0 else { return body() }
        defer { close(fd) }
        flock(fd, LOCK_EX)
        defer { flock(fd, LOCK_UN) }
        return body()
    }
}

extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("readingSession") }
}

enum ShieldController {
    static func clear() {
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
    }
}

enum ReadingActivityName {
    private static let prefix = "reading."

    static func make(for sessionID: UUID) -> DeviceActivityName {
        DeviceActivityName(prefix + sessionID.uuidString)
    }

    static func sessionID(from name: DeviceActivityName) -> UUID? {
        guard name.rawValue.hasPrefix(prefix) else { return nil }
        return UUID(uuidString: String(name.rawValue.dropFirst(prefix.count)))
    }
}

/// Idempotent: whichever side runs first (monitor extension or app) finishes the session, the other one does nothing.
enum SessionFinalizer {
    @discardableResult
    static func finish(sessionID: UUID) -> Bool {
        finish { $0.id == sessionID }
    }

    /// App-side fallback in case the monitor extension did not run.
    @discardableResult
    static func finishIfExpired(now: Date = .now) -> Bool {
        finish { now >= $0.endDate }
    }

    private static func finish(when isDue: (ReadingSession) -> Bool) -> Bool {
        SharedStore.update { state in
            guard let session = state.activeSession, isDue(session) else { return false }
            ShieldController.clear()
            state.activeSession = nil
            state.minutesByDay[DayKey.make(for: session.startDate), default: 0] += session.plannedMinutes
            state.pendingAnnouncement = true
            return true
        }
    }
}
```

