### 3. `ReadingSessionManager.swift`
Только **приложение**.

```swift
import ActivityKit
import DeviceActivity
import FamilyControls
import Foundation
import ManagedSettings
import Observation
import os

private let logger = Logger(subsystem: "Slumpy", category: "ReadingSessionManager")

@MainActor
@Observable
final class ReadingSessionManager {
    private(set) var activeSession: ReadingSession?
    private(set) var todayMinutes = 0
    var slumpyAnnouncement: String?

    @ObservationIgnored private var finishTask: Task<Void, Never>?

    init() {
        apply(SharedStore.read())
    }

    func start(minutes: Int, blocking selection: FamilyActivitySelection) throws {
        let now = Date.now
        let session = ReadingSession(
            id: UUID(),
            startDate: now,
            endDate: now.addingTimeInterval(TimeInterval(minutes * 60)),
            plannedMinutes: minutes
        )

        try startMonitoring(session)
        ShieldController.apply(selection)
        let state = SharedStore.update { state in
            state.activeSession = session
            state.pendingAnnouncement = false
            return state
        }
        startLiveActivity(for: session)
        apply(state)
    }

    /// Call whenever the app becomes active.
    func reconcile() async {
        SessionFinalizer.finishIfExpired()
        let (state, announce) = SharedStore.update { state in
            let announce = state.pendingAnnouncement
            state.pendingAnnouncement = false
            return (state, announce)
        }
        if state.activeSession == nil {
            await endLiveActivities()
        }
        apply(state)
        if announce {
            slumpyAnnouncement = "Сессия окончена"
        }
    }

    private func apply(_ state: SharedState) {
        activeSession = state.activeSession
        todayMinutes = state.minutes(on: .now)
        finishTask?.cancel()
        finishTask = nil
        if let session = state.activeSession {
            scheduleInAppFinish(for: session)
        }
    }

    /// Covers the case when the app is on screen at the moment the session ends.
    private func scheduleInAppFinish(for session: ReadingSession) {
        finishTask = Task { [weak self] in
            try? await Task.sleep(for: .seconds(max(0, session.endDate.timeIntervalSinceNow) + 1))
            guard !Task.isCancelled else { return }
            await self?.reconcile()
        }
    }

    private func startMonitoring(_ session: ReadingSession) throws {
        let center = DeviceActivityCenter()
        let previous = center.activities.filter { ReadingActivityName.sessionID(from: $0) != nil }
        // An empty list would stop all monitoring, including unrelated schedules.
        if !previous.isEmpty {
            center.stopMonitoring(previous)
        }

        // DeviceActivity rejects intervals shorter than 15 minutes; only the end moment matters here,
        // so short sessions get a window that starts earlier.
        let windowStart = min(session.startDate, session.endDate.addingTimeInterval(-15 * 60))
        let schedule = DeviceActivitySchedule(
            intervalStart: components(of: windowStart),
            intervalEnd: components(of: session.endDate),
            repeats: false
        )
        try center.startMonitoring(ReadingActivityName.make(for: session.id), during: schedule)
    }

    private func components(of date: Date) -> DateComponents {
        Calendar.current.dateComponents(
            [.calendar, .timeZone, .year, .month, .day, .hour, .minute, .second],
            from: date
        )
    }

    private func startLiveActivity(for session: ReadingSession) {
        let state = ReadingSessionAttributes.ContentState(startDate: session.startDate, endDate: session.endDate)
        // staleDate lets the system switch the card to its "finished" look on time even if the app is not running.
        let content = ActivityContent(state: state, staleDate: session.endDate)
        do {
            _ = try Activity<ReadingSessionAttributes>.request(
                attributes: ReadingSessionAttributes(),
                content: content,
                pushType: nil
            )
        } catch {
            // The session itself still works without a Live Activity.
            logger.error("Failed to start Live Activity: \(error)")
        }
    }

    private func endLiveActivities() async {
        for activity in Activity<ReadingSessionAttributes>.activities {
            await activity.end(nil, dismissalPolicy: .immediate)
        }
    }
}

extension ShieldController {
    static func apply(_ selection: FamilyActivitySelection) {
        let store = ManagedSettingsStore(named: .readingSession)
        store.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
        store.shield.applicationCategories = selection.categoryTokens.isEmpty ? nil : .specific(selection.categoryTokens)
        store.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens
    }
}
```

### 4. `SlumpyDeviceActivityMonitor.swift`
Только **расширение DeviceActivityMonitor**. Если в расширении уже есть свой класс, перенесите метод `intervalDidEnd` в него. Если такой метод там уже есть, добавьте эти строки в его конец.

```swift
import DeviceActivity

final class SlumpyDeviceActivityMonitor: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard let sessionID = ReadingActivityName.sessionID(from: activity) else { return }
        SessionFinalizer.finish(sessionID: sessionID)
    }
}
```

### 5. `ReadingSessionLiveActivity.swift`
Только **виджет**. Он заменяет текущий виджет Live Activity для сессии чтения. В `WidgetBundle` нужно указать `ReadingSessionLiveActivity()`.

```swift
import ActivityKit
import SwiftUI
import WidgetKit

struct ReadingSessionLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: ReadingSessionAttributes.self) { context in
            ReadingSessionActivityView(state: context.state, isFinished: context.isStale)
                .padding()
        } dynamicIsland: { context in
            DynamicIsland {
                DynamicIslandExpandedRegion(.bottom) {
                    ReadingSessionActivityView(state: context.state, isFinished: context.isStale)
                }
            } compactLeading: {
                Image(systemName: "book.fill")
            } compactTrailing: {
                if context.isStale {
                    Image(systemName: "checkmark")
                } else {
                    Text(timerInterval: context.state.startDate...context.state.endDate, countsDown: true)
                        .monospacedDigit()
                        .frame(width: 44)
                }
            } minimal: {
                Image(systemName: context.isStale ? "checkmark" : "book.fill")
            }
        }
    }
}

private struct ReadingSessionActivityView: View {
    let state: ReadingSessionAttributes.ContentState
    let isFinished: Bool

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: isFinished ? "checkmark.circle.fill" : "book.fill")
                .font(.title2)
            Text(isFinished ? "Сессия окончена" : "Сессия чтения")
                .font(.headline)
            Spacer()
            if !isFinished {
                Text(timerInterval: state.startDate...state.endDate, countsDown: true)
                    .monospacedDigit()
                    .font(.title2.bold())
            }
        }
    }
}
```

### 6. Вставки в существующий код приложения

В файл с `@main` (название структуры может отличаться):

```swift
@main
struct SlumpyApp: App {
    @State private var sessions = ReadingSessionManager()
    @Environment(\.scenePhase) private var scenePhase

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(sessions)
        }
        .onChange(of: scenePhase) { _, phase in
            if phase == .active {
                Task { await sessions.reconcile() }
            }
        }
    }
}
```

На экране, где говорит Slumpy:

```swift
@Environment(ReadingSessionManager.self) private var sessions

// ...on the root view of that screen:
.onChange(of: sessions.slumpyAnnouncement, initial: true) { _, message in
    guard let message else { return }
    slumpy.say(message) // replace with your existing Slumpy speech call
    sessions.slumpyAnnouncement = nil
}
```

Кнопка «Начать сессию» должна вызывать `try sessions.start(minutes: 30, blocking: selection)`, где `selection` — выбор приложений из FamilyControls, который у вас уже сохраняется. Минуты за сегодня для дневной цели берутся из `sessions.todayMinutes`.

## Ключевые решения

- **Окончание обрабатывает системное расширение, а не таймер в приложении.** Таймер выгруженного приложения не сработает, а DeviceActivityMonitor iOS запускает сама в назначенное время.
- **Всё повторяется при открытии приложения.** Если расширение не сработало, приложение доделает то же самое, а минуты не засчитаются дважды.
- **Отдельное хранилище блокировки «readingSession».** Снятие блокировки после сессии не затронет другие ограничения, если они у вас есть.
- **Данные лежат в файле в App Group**, защищённом от одновременной записи приложением и расширением. Файл доступен и на заблокированном телефоне: на момент окончания телефон обычно лежит заблокированным.

## Допущения

1. **Live Activity:** если приложение выгружено, iOS без сервера push-уведомлений не даёт убрать карточку ровно в момент окончания. Поэтому карточка вовремя переключается на «Сессия окончена», а исчезает при следующем открытии приложения или если пользователь смахнёт её сам. Это ограничение системы.
2. Засчитываются запланированные минуты (30). Они идут в тот день, когда сессия началась, даже если она закончилась после полуночи.
3. Досрочную остановку сессии я не делал, в задаче её не было.
4. **Ваш текущий код блокировки нужно заменить на `ShieldController.apply(selection)`.** Если блокировку ставит старый код в другое хранилище, новый код её не снимет.
5. Дневная цель берёт минуты из `todayMinutes`. Если цель сейчас хранится в другом месте, нужно поменять одну строку в `SessionFinalizer.finish` (там, где прибавляются минуты).
6. Система может снять блокировку и засчитать минуты с опозданием примерно до минуты: так работает её расписание.
7. Сессии короче 15 минут тоже работают: для них расписание начинается раньше, а важен только момент окончания.
8. В `AppGroup.id` нужно подставить ваш настоящий идентификатор App Group. Вызов `slumpy.say(...)` нужно заменить на тот, которым Slumpy говорит у вас.

