            return (state, announce)
        }
        if state.activeSession == nil {
            await endLiveActivities()
        }
        apply(state)
        if announce {
            slumpyAnnouncement = "Сессия окончена"
        }
    }

    private func apply(_ state: SharedState) {
        activeSession = state.activeSession
        todayMinutes = state.minutes(on: .now)
        finishTask?.cancel()
        finishTask = nil
        if let session = state.activeSession {
            scheduleInAppFinish(for: session)
        }
    }

    /// Covers the case when the app is on screen at the moment the session ends.
    private func scheduleInAppFinish(for session: ReadingSession) {
        finishTask = Task { [weak self] in
            try? await Task.sleep(for: .seconds(max(0, session.endDate.timeIntervalSinceNow) + 1))
            guard !Task.isCancelled else { return }
            await self?.reconcile()
        }
    }

    private func startMonitoring(_ session: ReadingSession) throws {
        let center = DeviceActivityCenter()
        let previous = center.activities.filter { ReadingActivityName.sessionID(from: $0) != nil }
        // An empty list would stop all monitoring, including unrelated schedules.
        if !previous.isEmpty {
            center.stopMonitoring(previous)
        }

        // DeviceActivity rejects intervals shorter than 15 minutes; only the end moment matters here,
        // so short sessions get a window that starts earlier.
        let windowStart = min(session.startDate, session.endDate.addingTimeInterval(-15 * 60))
        let schedule = DeviceActivitySchedule(
            intervalStart: components(of: windowStart),
            intervalEnd: components(of: session.endDate),
            repeats: false
        )
        try center.startMonitoring(ReadingActivityName.make(for: session.id), during: schedule)
    }

    private func components(of date: Date) -> DateComponents {
        Calendar.current.dateComponents(
            [.calendar, .timeZone, .year, .month, .day, .hour, .minute, .second],
            from: date
        )
    }

    private func startLiveActivity(for session: ReadingSession) {
        let state = ReadingSessionAttributes.ContentState(startDate: session.startDate, endDate: session.endDate)
        // staleDate lets the system switch the card to its "finished" look on time even if the app is not running.
        let content = ActivityContent(state: state, staleDate: session.endDate)
        do {
            _ = try Activity<ReadingSessionAttributes>.request(
                attributes: ReadingSessionAttributes(),
                content: content,
                pushType: nil
            )
        } catch {
            // The session itself still works without a Live Activity.
            logger.error("Failed to start Live Activity: \(error)")
        }
    }

    private func endLiveActivities() async {
        for activity in Activity<ReadingSessionAttributes>.activities {
            await activity.end(nil, dismissalPolicy: .immediate)
        }
    }
}

extension ShieldController {
    static func apply(_ selection: FamilyActivitySelection) {
        let store = ManagedSettingsStore(named: .readingSession)
        store.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
        store.shield.applicationCategories = selection.categoryTokens.isEmpty ? nil : .specific(selection.categoryTokens)
        store.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens
